    private static int[] logical(ActorFusedInput.View view,int row){int[] result=new int[32];for(int i=0;i<32;i++)result[i]=view.word(row*32+i);int m=view.metadataBase+row*4;if(view.word(m)==0)return result;int t=view.word(m+1);float d=Float.intBitsToFloat(view.word(m+2));float[] tick=new float[16];for(int i=0;i<16;i++)tick[i]=Float.intBitsToFloat(view.word(t+i));result[16]=bits(tick[6]-tick[7]*(1-d));result[17]=bits(Math.min(1,tick[8]+(tick[7]-tick[8])*d));result[18]=bits(tick[9]+d);result[19]=bits(angle(tick[2],tick[3],d)-angle(tick[0],tick[1],d));result[20]=bits(tick[4]+(tick[5]-tick[4])*d);int descriptor=view.word(m+3),offset=descriptor>>>5;for(int i=0;i<5;i++)if((descriptor&(1<<i))!=0)result[16+i]=view.word(offset++);return result;}
